import cocotb
from cocotb.clock import Clock
from cocotb.triggers import RisingEdge, FallingEdge, Timer

# Generated by Nishkam Studio from the scan chain and Quaigh patterns (issue #10, early, not validated).
# Chain order: q[0], q[1], q[2], q[3] (first flop after scan_in). 6 patterns.
@cocotb.test()
async def scan_chain_patterns(dut):
    cocotb.start_soon(Clock(dut.clk, 10, units="ns").start())
    dut.scan_in.value = 0
    # pattern 1 of 6
    dut.scan_en.value = 1
    await FallingEdge(dut.clk)
    dut.scan_in.value = 0
    await RisingEdge(dut.clk)
    await FallingEdge(dut.clk)
    dut.scan_in.value = 0
    await RisingEdge(dut.clk)
    await FallingEdge(dut.clk)
    dut.scan_in.value = 0
    await RisingEdge(dut.clk)
    await FallingEdge(dut.clk)
    dut.scan_in.value = 1
    await RisingEdge(dut.clk)
    await FallingEdge(dut.clk)
    dut.scan_en.value = 0
    dut.rst.value = 0
    await Timer(1, units="ns")
    assert int(dut.q.value) == 1, "pattern 1: output q is wrong"
    await RisingEdge(dut.clk)
    dut.scan_en.value = 1
    await FallingEdge(dut.clk)
    assert int(dut.scan_out.value) == 0, "pattern 1: captured flop 3 is wrong"
    await RisingEdge(dut.clk)
    await FallingEdge(dut.clk)
    assert int(dut.scan_out.value) == 0, "pattern 1: captured flop 2 is wrong"
    await RisingEdge(dut.clk)
    await FallingEdge(dut.clk)
    assert int(dut.scan_out.value) == 1, "pattern 1: captured flop 1 is wrong"
    await RisingEdge(dut.clk)
    await FallingEdge(dut.clk)
    assert int(dut.scan_out.value) == 0, "pattern 1: captured flop 0 is wrong"
    await RisingEdge(dut.clk)

    # pattern 2 of 6
    dut.scan_en.value = 1
    await FallingEdge(dut.clk)
    dut.scan_in.value = 1
    await RisingEdge(dut.clk)
    await FallingEdge(dut.clk)
    dut.scan_in.value = 1
    await RisingEdge(dut.clk)
    await FallingEdge(dut.clk)
    dut.scan_in.value = 0
    await RisingEdge(dut.clk)
    await FallingEdge(dut.clk)
    dut.scan_in.value = 0
    await RisingEdge(dut.clk)
    await FallingEdge(dut.clk)
    dut.scan_en.value = 0
    dut.rst.value = 0
    await Timer(1, units="ns")
    assert int(dut.q.value) == 12, "pattern 2: output q is wrong"
    await RisingEdge(dut.clk)
    dut.scan_en.value = 1
    await FallingEdge(dut.clk)
    assert int(dut.scan_out.value) == 1, "pattern 2: captured flop 3 is wrong"
    await RisingEdge(dut.clk)
    await FallingEdge(dut.clk)
    assert int(dut.scan_out.value) == 1, "pattern 2: captured flop 2 is wrong"
    await RisingEdge(dut.clk)
    await FallingEdge(dut.clk)
    assert int(dut.scan_out.value) == 0, "pattern 2: captured flop 1 is wrong"
    await RisingEdge(dut.clk)
    await FallingEdge(dut.clk)
    assert int(dut.scan_out.value) == 1, "pattern 2: captured flop 0 is wrong"
    await RisingEdge(dut.clk)

    # pattern 3 of 6
    dut.scan_en.value = 1
    await FallingEdge(dut.clk)
    dut.scan_in.value = 1
    await RisingEdge(dut.clk)
    await FallingEdge(dut.clk)
    dut.scan_in.value = 0
    await RisingEdge(dut.clk)
    await FallingEdge(dut.clk)
    dut.scan_in.value = 1
    await RisingEdge(dut.clk)
    await FallingEdge(dut.clk)
    dut.scan_in.value = 1
    await RisingEdge(dut.clk)
    await FallingEdge(dut.clk)
    dut.scan_en.value = 0
    dut.rst.value = 0
    await Timer(1, units="ns")
    assert int(dut.q.value) == 11, "pattern 3: output q is wrong"
    await RisingEdge(dut.clk)
    dut.scan_en.value = 1
    await FallingEdge(dut.clk)
    assert int(dut.scan_out.value) == 1, "pattern 3: captured flop 3 is wrong"
    await RisingEdge(dut.clk)
    await FallingEdge(dut.clk)
    assert int(dut.scan_out.value) == 1, "pattern 3: captured flop 2 is wrong"
    await RisingEdge(dut.clk)
    await FallingEdge(dut.clk)
    assert int(dut.scan_out.value) == 0, "pattern 3: captured flop 1 is wrong"
    await RisingEdge(dut.clk)
    await FallingEdge(dut.clk)
    assert int(dut.scan_out.value) == 0, "pattern 3: captured flop 0 is wrong"
    await RisingEdge(dut.clk)

    # pattern 4 of 6
    dut.scan_en.value = 1
    await FallingEdge(dut.clk)
    dut.scan_in.value = 1
    await RisingEdge(dut.clk)
    await FallingEdge(dut.clk)
    dut.scan_in.value = 1
    await RisingEdge(dut.clk)
    await FallingEdge(dut.clk)
    dut.scan_in.value = 1
    await RisingEdge(dut.clk)
    await FallingEdge(dut.clk)
    dut.scan_in.value = 0
    await RisingEdge(dut.clk)
    await FallingEdge(dut.clk)
    dut.scan_en.value = 0
    dut.rst.value = 1
    await Timer(1, units="ns")
    assert int(dut.q.value) == 14, "pattern 4: output q is wrong"
    await RisingEdge(dut.clk)
    dut.scan_en.value = 1
    await FallingEdge(dut.clk)
    assert int(dut.scan_out.value) == 0, "pattern 4: captured flop 3 is wrong"
    await RisingEdge(dut.clk)
    await FallingEdge(dut.clk)
    assert int(dut.scan_out.value) == 0, "pattern 4: captured flop 2 is wrong"
    await RisingEdge(dut.clk)
    await FallingEdge(dut.clk)
    assert int(dut.scan_out.value) == 0, "pattern 4: captured flop 1 is wrong"
    await RisingEdge(dut.clk)
    await FallingEdge(dut.clk)
    assert int(dut.scan_out.value) == 0, "pattern 4: captured flop 0 is wrong"
    await RisingEdge(dut.clk)

    # pattern 5 of 6
    dut.scan_en.value = 1
    await FallingEdge(dut.clk)
    dut.scan_in.value = 1
    await RisingEdge(dut.clk)
    await FallingEdge(dut.clk)
    dut.scan_in.value = 1
    await RisingEdge(dut.clk)
    await FallingEdge(dut.clk)
    dut.scan_in.value = 1
    await RisingEdge(dut.clk)
    await FallingEdge(dut.clk)
    dut.scan_in.value = 0
    await RisingEdge(dut.clk)
    await FallingEdge(dut.clk)
    dut.scan_en.value = 0
    dut.rst.value = 0
    await Timer(1, units="ns")
    assert int(dut.q.value) == 14, "pattern 5: output q is wrong"
    await RisingEdge(dut.clk)
    dut.scan_en.value = 1
    await FallingEdge(dut.clk)
    assert int(dut.scan_out.value) == 1, "pattern 5: captured flop 3 is wrong"
    await RisingEdge(dut.clk)
    await FallingEdge(dut.clk)
    assert int(dut.scan_out.value) == 1, "pattern 5: captured flop 2 is wrong"
    await RisingEdge(dut.clk)
    await FallingEdge(dut.clk)
    assert int(dut.scan_out.value) == 1, "pattern 5: captured flop 1 is wrong"
    await RisingEdge(dut.clk)
    await FallingEdge(dut.clk)
    assert int(dut.scan_out.value) == 1, "pattern 5: captured flop 0 is wrong"
    await RisingEdge(dut.clk)

    # pattern 6 of 6
    dut.scan_en.value = 1
    await FallingEdge(dut.clk)
    dut.scan_in.value = 0
    await RisingEdge(dut.clk)
    await FallingEdge(dut.clk)
    dut.scan_in.value = 1
    await RisingEdge(dut.clk)
    await FallingEdge(dut.clk)
    dut.scan_in.value = 1
    await RisingEdge(dut.clk)
    await FallingEdge(dut.clk)
    dut.scan_in.value = 1
    await RisingEdge(dut.clk)
    await FallingEdge(dut.clk)
    dut.scan_en.value = 0
    dut.rst.value = 0
    await Timer(1, units="ns")
    assert int(dut.q.value) == 7, "pattern 6: output q is wrong"
    await RisingEdge(dut.clk)
    dut.scan_en.value = 1
    await FallingEdge(dut.clk)
    assert int(dut.scan_out.value) == 1, "pattern 6: captured flop 3 is wrong"
    await RisingEdge(dut.clk)
    await FallingEdge(dut.clk)
    assert int(dut.scan_out.value) == 0, "pattern 6: captured flop 2 is wrong"
    await RisingEdge(dut.clk)
    await FallingEdge(dut.clk)
    assert int(dut.scan_out.value) == 0, "pattern 6: captured flop 1 is wrong"
    await RisingEdge(dut.clk)
    await FallingEdge(dut.clk)
    assert int(dut.scan_out.value) == 0, "pattern 6: captured flop 0 is wrong"
    await RisingEdge(dut.clk)
